const CHAIN={S:100,d:30,v:.30,ks:[90,92.5,95,97.5,100,102.5,105,107.5,110]};
function chainRows(S=CHAIN.S){return CHAIN.ks.map(K=>{const c=bs(S,K,CHAIN.d/365,CHAIN.v,true),p=bs(S,K,CHAIN.d/365,CHAIN.v,false);
 const q=x=>{const sp=Math.max(.05,Math.round(x*.04/.05)*.05);return{bid:Math.max(.01,Math.round((x-sp/2)*100)/100),ask:Math.round((x+sp/2)*100)/100}};
 const oi=Math.round(400+5200*Math.exp(-Math.pow((K-100)/7,2))),vol=Math.round(oi*.31);return{K,c:{...q(c.price),delta:c.delta,vol,oi},p:{...q(p.price),delta:p.delta,vol:Math.round(vol*.8),oi:Math.round(oi*.85)}}})}
function chainHTML(S=CHAIN.S,mark=true){return `<div class="chainwrap"><div class="chaincap">PRAC (practice stock) $${S.toFixed(2)} • expires in ${CHAIN.d} days • <b>practice data, not real</b></div><table class="chain"><thead><tr><th colspan="5" class="cg">CALLS</th><th></th><th colspan="5" class="cr">PUTS</th></tr><tr><th>Vol</th><th>OI</th><th>Δ</th><th>Bid</th><th>Ask</th><th>Strike</th><th>Bid</th><th>Ask</th><th>Δ</th><th>OI</th><th>Vol</th></tr></thead><tbody>${chainRows(S).map((r,i)=>`<tr class="row-in" style="animation-delay:${i*.08}s"><td>${r.c.vol}</td><td>${r.c.oi}</td><td>${r.c.delta.toFixed(2)}</td><td data-c="cb${r.K}" class="${mark&&r.K<S?'itm':''}">${r.c.bid.toFixed(2)}</td><td data-c="ca${r.K}" class="${mark&&r.K<S?'itm':''}">${r.c.ask.toFixed(2)}</td><td class="k">${r.K}</td><td data-c="pb${r.K}" class="${mark&&r.K>S?'itm':''}">${r.p.bid.toFixed(2)}</td><td data-c="pa${r.K}" class="${mark&&r.K>S?'itm':''}">${r.p.ask.toFixed(2)}</td><td>${r.p.delta.toFixed(2)}</td><td>${r.p.oi}</td><td>${r.p.vol}</td></tr>`).join('')}</tbody></table></div>`}
