LS.push({id:'decay',emoji:'🧊',title:'Intrinsic vs time value',sub:'Time decay = a melting ice cube',
scenes:[
{t:'Every premium has two parts: <b>Premium = Intrinsic value + Time value</b>. <i>Example:</i> the stock is $100, and the 95 call costs $6.50. Intrinsic = $100 − $95 = <b>$5</b>. Time value = $6.50 − $5 = <b>$1.50</b>.',
 a:()=>svg(`<rect x="230" y="120" width="140" height="150" class="growbar" fill="#4ade80"/><rect x="230" y="75" width="140" height="45" class="growbar" style="animation-delay:1s" fill="#60a5fa"/>`+T(470,200,'Intrinsic $5.00','#4ade80',20,'popin',.8)+T(470,103,'Time $1.50','#60a5fa',20,'popin',1.6)+T(120,150,'$6.50','#facc15',34,'popin',2.2)+T(120,180,'premium','#facc15',15,'popin',2.2),300)},
{t:'<b>Intrinsic value</b> is the in-the-money amount, and it\'s <b>never below zero</b>. For a call: stock − strike. For a put: strike − stock. OTM options have <b>$0 intrinsic</b>, so their whole price is time value.',
 a:()=>svg(box(50,60,240,70,'#4ade80','Call: Stock − Strike','#0b1020',18)+box(310,60,240,70,'#f87171','Put: Strike − Stock','#0b1020',18,.4)+T(300,190,'If the answer is negative → intrinsic = $0','#facc15',19,'popin',1)+T(300,240,'(you just wouldn\'t use the option)','#9fb0d0',16,'popin',1.4))},
{t:'<b>Time value</b> is like an <b>ice cube melting</b> 🧊. Every day, a little melts away. This is called <b>time decay</b>, and its daily speed is a Greek called <b>theta</b>. At expiration, the time value is <b>completely gone</b>.',
 a:()=>svg(iceCube(300,250,'TIME VALUE')+`<text x="300" y="50" font-size="36" text-anchor="middle" class="spin">☀️</text>`+T(300,292,'Every day a little melts…','#93c5fd',16,'popin',1))},
{t:'The melting <b>speeds up near expiration</b>, especially for at-the-money options. In the last few weeks, time value disappears fastest. This curve comes from the pricing model.',
 a:()=>{const pts=[];for(let d=120;d>=0;d-=2)pts.push(bs(100,100,d/365,.3).price);const c=lineChart(pts,{lo:0,hi:Math.max(...pts)+.5,col:'#60a5fa',y0:40,y1:240});return svg(c.s+T(110,272,'120 days left','#9fb0d0',14,'')+T(520,272,'expiration','#9fb0d0',14,'')+T(440,80,'Melts fastest at the end ⚡','#facc15',17,'popin',2.2)+T(200,28,'100 call on a $100 stock (model)','#60a5fa',14,''))}}],
take:['Premium = intrinsic value + time value.','Intrinsic = how far ITM (never negative). OTM options have $0 intrinsic.','Time value melts every day (theta), and fastest near expiration.','At expiration, an option is worth exactly its intrinsic value.'],
tryit:el=>{el.innerHTML=`<h3>🧊 Melt the time value</h3><p>The stock is <b>$100</b>, and volatility is 30%. Pick an option, then slide time toward expiration.</p>${seg('mk',[['95','95 call (ITM)'],['100','100 call (ATM)'],['105','105 call (OTM)']],'100')}${slider('md','Days left',0,120,1,60)}<div id="mdo" class="outbox"></div>${SIM}`;
 const f=()=>{const K=+segVal(el,'mk'),d=val('md');setv('md',d);const g=bs(100,K,d/365,.3),p=g.price,iv=Math.max(100-K,0),tv=Math.max(p-iv,0),tv0=bs(100,K,120/365,.3).price-iv,sc=Math.max(.03,tv/tv0);
 $('#mdo').innerHTML=svg(`<g transform="translate(150,250) scale(1,${sc.toFixed(3)})"><rect x="-70" y="-160" width="140" height="160" rx="16" fill="#93c5fd"/></g><text x="150" y="${242-160*sc}" font-size="15" font-weight="800" fill="#93c5fd" text-anchor="middle">Time $${tv.toFixed(2)}</text><ellipse cx="150" cy="256" rx="${70+(1-sc)*50}" ry="8" fill="#60a5fa" opacity=".6"/>
 <rect x="360" y="${250-iv*20}" width="120" height="${iv*20}" fill="#4ade80"/><rect x="360" y="${250-iv*20-tv*20}" width="120" height="${tv*20}" fill="#60a5fa"/><text x="420" y="${240-iv*20-tv*20}" font-size="16" font-weight="800" fill="#facc15" text-anchor="middle">$${p.toFixed(2)}</text><text x="420" y="285" font-size="14" fill="#cbd5ee" text-anchor="middle">green = intrinsic, blue = time</text>`,300)+`<p>Price <b class="y">$${p.toFixed(2)}</b> = intrinsic <b class="g">$${iv.toFixed(2)}</b> + time <b class="b">$${tv.toFixed(2)}</b>.${d>0?` Theta: about <b>${money(g.theta*100)}</b> per day per contract.`:' Expired, so there\'s no time value left.'}</p>`};bindSeg(el,f);onAll(el,f)},
quiz:[
{q:'The stock is $50, and the 45 call costs $6. What is its time value?',o:[['$1'],['$6','$6 is the whole premium. Take out the $5 intrinsic value.'],['$5','$5 is the intrinsic part.'],['$0','Before expiration there\'s usually some time value left.']],a:0,ex:'Intrinsic = $50 − $45 = $5. Time = $6 − $5 = $1.'},
{q:'What is the intrinsic value of an OUT-of-the-money option?',o:[['$0'],['Negative','Intrinsic value is never below zero.'],['Equal to the premium','The premium of an OTM option is all time value, not intrinsic.'],['$100','That isn\'t how intrinsic value works.']],a:0,ex:'If you wouldn\'t use the option right now, its intrinsic value is $0.'},
{q:'When does time decay usually happen FASTEST?',o:[['In the last few weeks before expiration'],['Right after the option is listed','Decay is slow when there\'s lots of time left.'],['Evenly every day','Decay speeds up as expiration nears.'],['Only on weekends','Decay happens with the calendar. Prices just adjust when the market reopens.']],a:0,ex:'Like an ice cube that shrinks faster near the end, theta grows as expiration approaches, especially for ATM options.'},
{q:'At expiration, an option is worth…',o:[['Only its intrinsic value'],['Its original premium','Premiums aren\'t locked in, and the time value is gone.'],['Intrinsic + time value','At expiration, time value is $0.'],['Always $0','ITM options still have intrinsic value.']],a:0,ex:'No time left means no time value. Only intrinsic value remains.'}]});

/* ---------- 9 ---------- */
LS.push({id:'iv',emoji:'🌊',title:'Implied volatility (IV)',sub:'The market\'s "how jumpy?" estimate',
scenes:[
{t:'<b>Volatility</b> = how much a price bounces around. A calm stock moves in small waves 🌊, and a wild stock moves in big waves. Big waves mean a better chance an option ends up in the money, so options cost <b>more</b>.',
 a:()=>svg(`<path d="M-100 100 Q-50 85 0 100 T100 100 T200 100 T300 100 T400 100 T500 100 T600 100 T700 100" stroke="#4ade80" stroke-width="4" fill="none" class="wave-x"/><path d="M-100 200 Q-50 120 0 200 T100 200 T200 200 T300 200 T400 200 T500 200 T600 200 T700 200" stroke="#f87171" stroke-width="4" fill="none" class="wave-x" style="animation-duration:1.4s"/>`+T(300,50,'Calm stock → low volatility → cheaper options','#4ade80',16,'popin')+T(300,290,'Wild stock → high volatility → pricier options','#f87171',16,'popin',.6))},
{t:'<b>Implied volatility (IV)</b> is the volatility that\'s <b>"baked into" option prices</b>. It\'s the market\'s estimate of how big moves might be over a year, shown as a %. <b>Higher IV = higher premiums</b> for both calls and puts.',
 a:()=>svg(`<g transform="translate(300,150)"><circle r="45" fill="#f472b6" class="inflate"/><path d="M0 45 Q-6 90 4 130" stroke="#cbd5ee" stroke-width="2" fill="none"/></g>`+T(300,32,'IV goes up → option prices puff up 🎈','#f472b6',18,'popin'))},
{t:'A rough <b>expected move</b> (about one standard deviation) = <b>price × IV × √(days ÷ 365)</b>. <i>Example:</i> a $100 stock, IV 30%, 30 days: 100 × 0.30 × √(30/365) ≈ <b>$8.60</b>. The model says the stock lands within about ±$8.60 roughly 68% of the time. It\'s an estimate, not a promise.',
 a:()=>{let p='';for(let i=0;i<=120;i++){const x=i/120*6-3;p+=(i?'L':'M')+(60+i*4)+' '+(250-170*Math.exp(-x*x/2)).toFixed(1)}return svg(`<path d="${p}" stroke="#60a5fa" stroke-width="4" fill="#60a5fa22" class="draw" pathLength="1"/><rect x="220" y="80" width="160" height="170" fill="#4ade8033" class="popin" style="animation-delay:1.4s"/>`+T(300,60,'$91.40  ←  ~68%  →  $108.60','#4ade80',18,'popin',1.8)+T(300,285,'Stock $100, IV 30%, 30 days (model estimate)','#9fb0d0',14,''))}},
{t:'<b>IV crush</b> 💥: before big news like earnings, IV is often high, so options are pricey. After the news, IV often <b>drops fast</b> and option prices shrink, <b>even if the stock moved your way</b>. This catches many beginners.',
 a:()=>svg(`<g transform="translate(160,150)"><circle r="70" fill="#f472b6" class="crush"/></g>`+T(160,270,'Before earnings: IV high','#f472b6',16,'')+arrow(260,150,360,150,'#facc15',.6)+`<g transform="translate(450,170)"><circle r="30" fill="#f472b6" class="popin" style="animation-delay:1.2s"/></g>`+T(450,270,'After: IV crushed','#f472b6',16,'popin',1.2)+T(300,40,'Your option can lose value even if you guessed right!','#facc15',16,'popin',1.8))},
{t:'Remember: IV says <b>how much</b> the market expects the stock to move, <b>not which direction</b>. High IV on its own is not a "buy signal" or a "sell signal".',
 a:()=>svg(arrow(300,150,300,50,'#4ade80')+arrow(300,150,300,250,'#f87171',.3)+arrow(300,150,480,150,'#60a5fa',.6)+arrow(300,150,120,150,'#60a5fa',.9)+emo(300,165,'❓',40,'popin',1.2)+T(470,60,'IV = size of move, not direction','#facc15',16,'popin',1.6))}],
take:['IV is the market\'s estimate of future movement, built into option prices.','Higher IV → higher premiums for calls AND puts.','Expected move ≈ price × IV × √(days ÷ 365). It\'s only a rough estimate.','<b>IV crush</b> after events can shrink option prices fast. IV is about size, not direction.'],
tryit:el=>{el.innerHTML=`<h3>🌊 IV lab</h3><p>The stock is <b>$100</b>, with a 100 strike. Raise or lower IV and the days left.</p>${slider('iv','Implied volatility',10,120,1,30)}${slider('idd','Days to expiration',1,120,1,30)}<div id="ivo" class="outbox"></div>${SIM}`;
 onAll(el,()=>{const v=val('iv')/100,d=val('idd');setv('iv',(v*100).toFixed(0)+'%');setv('idd',d);const c=bs(100,100,d/365,v).price,p=bs(100,100,d/365,v,false).price,em=100*v*Math.sqrt(d/365);const w=Math.min(em*12,250);
 $('#ivo').innerHTML=svg(`<rect x="${300-w}" y="60" width="${2*w}" height="80" rx="10" fill="#4ade8033" stroke="#4ade80"/><line x1="300" x2="300" y1="50" y2="150" stroke="#fff" stroke-width="2"/><text x="300" y="40" font-size="15" fill="#fff" text-anchor="middle">$100</text><text x="${Math.max(300-w,45)}" y="170" font-size="15" fill="#4ade80" text-anchor="middle">$${(100-em).toFixed(2)}</text><text x="${Math.min(300+w,555)}" y="170" font-size="15" fill="#4ade80" text-anchor="middle">$${(100+em).toFixed(2)}</text>
 <text x="300" y="215" font-size="18" font-weight="800" fill="#facc15" text-anchor="middle">Expected move: ±$${em.toFixed(2)}</text>`,230)+`<p>100 call ≈ <b class="g">$${c.toFixed(2)}</b> (${money(c*100)}) • 100 put ≈ <b class="r">$${p.toFixed(2)}</b> (${money(p*100)})</p>`})},
quiz:[
{q:'If implied volatility rises and nothing else changes, call and put prices usually…',o:[['Both go up'],['Calls go up, puts go down','IV raises both, because it\'s about the size of the move, not the direction.'],['Both go down','That\'s what happens when IV falls.'],['Stay the same','Vega makes prices react to IV.']],a:0,ex:'Bigger expected moves make both calls and puts more valuable.'},
{q:'A $200 stock has IV 25% and 30 days left. What is the rough expected move?',o:[['About $14'],['About $50','That uses a full year. Scale it by √(30/365).'],['About $1','That\'s far too small.'],['Exactly $25','IV is a yearly %, and you must adjust for time.']],a:0,ex:'200 × 0.25 × √(30/365) ≈ 200 × 0.25 × 0.287 ≈ $14.3.'},
{q:'What is "IV crush"?',o:[['A quick drop in IV, often right after earnings or big news'],['When the stock crashes','IV crush is about volatility, not price direction.'],['When an option is exercised','That\'s exercise, which is a different thing.'],['A broker fee','It\'s not a fee.']],a:0,ex:'Once the news is out, uncertainty drops, so IV and option prices often fall.'},
{q:'High IV tells you the stock will most likely go…',o:[['It doesn\'t tell you the direction, only the expected size of moves'],['Up','IV doesn\'t predict direction.'],['Down','IV doesn\'t predict direction.'],['Sideways','High IV actually suggests bigger moves.']],a:0,ex:'IV measures expected movement, up or down.'}]});
/* ---------- 10 ---------- */
LS.push({id:'greeks',emoji:'Δ',title:'The Greeks',sub:'Delta • Gamma • Theta • Vega',
scenes:[
{t:'The <b>Greeks</b> are like the gauges on a car dashboard 🚗. They tell you how your option\'s price will react to changes: <b>Delta</b> (stock price), <b>Gamma</b> (how fast delta changes), <b>Theta</b> (time) and <b>Vega</b> (volatility).',
 a:()=>svg(gauge(110,150,.5,'Δ Delta','#4ade80')+gauge(300,150,.75,'Γ Gamma','#60a5fa',.3)+gauge(490,150,.35,'Θ Theta','#f87171',.6)+T(300,260,'+ ν Vega 🎈','#f472b6',22,'popin',1))},
{t:'<b>Delta (Δ)</b> ≈ how much the option moves when the stock moves <b>$1</b>. Calls go from 0 to +1, and puts from 0 to −1. An ATM option is about <b>0.50</b>. <i>Example:</i> with delta 0.50, if the stock goes up $1, the option goes up about $0.50 (<b>+$50</b> per contract). Watch the needle as the stock moves.',
 run:st=>{let S=100,dir=1;const draw=()=>{const g=bs(S,100,30/365,.3);st.innerHTML=svg(`<text x="150" y="50" font-size="18" fill="#fff" font-weight="800" text-anchor="middle">Stock $${S}</text><text x="450" y="50" font-size="18" fill="#4ade80" font-weight="800" text-anchor="middle">100 call $${g.price.toFixed(2)}</text>`+gauge(300,190,g.delta,'Delta '+g.delta.toFixed(2),'#4ade80').replace('class="popin"','')+T(300,285,'Stock up → delta climbs toward 1. Stock down → toward 0','#facc15',15,''),300)};draw();every(()=>{S+=dir*2;if(S>=116||S<=84)dir*=-1;draw()},700)}},
{t:'<b>Gamma (Γ)</b> = how fast delta changes. Think of it as <b>acceleration</b> 🏎️. Gamma is highest for <b>at-the-money</b> options <b>near expiration</b>, so their deltas can swing quickly.',
 a:()=>{let p='',q='';for(let S=80;S<=120;S+=.5){const x=60+(S-80)*12.5;p+=(S>80?'L':'M')+x+' '+(250-bs(S,100,30/365,.3).gamma*2000).toFixed(1);q+=(S>80?'L':'M')+x+' '+(250-bs(S,100,7/365,.3).gamma*2000).toFixed(1)}return svg(`<line x1="60" x2="560" y1="250" y2="250" stroke="#334155"/><path d="${p}" stroke="#60a5fa" stroke-width="4" fill="none" class="draw" pathLength="1"/><path d="${q}" stroke="#facc15" stroke-width="4" fill="none" class="draw" pathLength="1" style="animation-delay:1s"/>`+T(470,60,'7 days left: tall spike','#facc15',15,'popin',2)+T(480,200,'30 days left','#60a5fa',15,'popin',1.2)+T(300,285,'Gamma vs stock price (strike $100, model)','#9fb0d0',14,''))}},
{t:'<b>Theta (Θ)</b> = how much value the option <b>loses per day</b> as time passes. Theta −0.05 means about <b>−$5 per day per contract</b>, all else equal. Option buyers fight theta, and option sellers collect it.',
 a:()=>svg(`<text x="160" y="190" font-size="110" text-anchor="middle" class="tick">⏰</text>`+iceCube(430,240,'−$5/day',.3)+T(300,290,'Theta: the daily melt','#f87171',17,'popin',1))},
{t:'<b>Vega (ν)</b> = how much the option price changes when IV moves <b>1 percentage point</b>. Vega 0.12 means IV +1 point ≈ <b>+$12</b> per contract. Longer-dated options have more vega.',
 a:()=>svg(`<g transform="translate(300,150)"><circle r="50" fill="#f472b6" class="inflate"/></g>`+T(300,40,'IV +1 point → price + vega','#f472b6',18,'popin')+T(300,280,'Vega 0.12 → about +$12 per contract','#facc15',16,'popin',.8))}],
take:['<b>Delta</b>: price change per $1 stock move (calls +, puts −, ATM ≈ 0.50).','<b>Gamma</b>: how fast delta changes. It\'s biggest ATM, near expiration.','<b>Theta</b>: daily time decay. Buyers lose it, and sellers gain it.','<b>Vega</b>: the change per 1-point IV move. It\'s bigger for longer-dated options.','The Greeks are estimates, and they change constantly as price, time and IV move.'],
tryit:el=>{el.innerHTML=`<h3>Δ Greek dashboard</h3>${seg('gt',[['c','Call'],['p','Put']],'c')}${slider('gS','Stock price',80,120,.5,100)}${slider('gD','Days left',1,120,1,30)}${slider('gI','IV',10,100,1,30)}<p class="mut">Strike $100. Black-Scholes model, with interest rates and dividends ignored to keep it simple.</p><div id="go" class="outbox"></div><button class="btn" id="g1">Move the stock +$1 and compare with delta</button><div id="g1o"></div>${SIM}`;
 const f=()=>{const c=segVal(el,'gt')==='c',S=val('gS'),d=val('gD'),v=val('gI')/100;setv('gS','$'+S.toFixed(2));setv('gD',d);setv('gI',(v*100).toFixed(0)+'%');const g=bs(S,100,d/365,v,c);$('#g1o').innerHTML='';
  $('#go').innerHTML=`<div class="gk"><div><b>Price</b><span class="y">$${g.price.toFixed(2)}</span><i>${money(g.price*100)} per contract</i></div><div><b>Δ Delta</b><span>${g.delta.toFixed(3)}</span><i>${smoney(g.delta*100,2)} per $1 move</i></div><div><b>Γ Gamma</b><span>${g.gamma.toFixed(4)}</span><i>delta change per $1</i></div><div><b>Θ Theta</b><span>${g.theta.toFixed(3)}</span><i>${money(g.theta*100)}/day per contract</i></div><div><b>ν Vega</b><span>${g.vega.toFixed(3)}</span><i>${smoney(g.vega*100,2)} per +1 IV point</i></div></div>`};
 bindSeg(el,f);onAll(el,f);$('#g1').onclick=()=>{const c=segVal(el,'gt')==='c',S=val('gS'),d=val('gD'),v=val('gI')/100,a=bs(S,100,d/365,v,c),b=bs(S+1,100,d/365,v,c);
  $('#g1o').innerHTML=`<div class="fbbox ok popin-h">Delta predicted about <b>$${(a.price+a.delta).toFixed(2)}</b>. The actual new model price is <b>$${b.price.toFixed(2)}</b>. The small difference is <b>gamma</b> at work.</div>`}},
quiz:[
{q:'A call has delta 0.40. The stock rises $1. About how much does one contract gain?',o:[['$40'],['$0.40','That\'s per share. One contract covers 100 shares.'],['$400','That would be a $10 stock move.'],['$100','Only a delta of 1.00 moves dollar for dollar with the shares.']],a:0,ex:'0.40 × $1 × 100 shares ≈ $40.'},
{q:'A PUT\'s delta is…',o:[['Between 0 and −1'],['Between 0 and +1','That\'s the range for calls.'],['Always exactly −0.50','It changes with price and time.'],['Greater than 1','Delta stays between −1 and +1 for a single option.']],a:0,ex:'Puts gain when the stock falls, so their delta is negative.'},
{q:'Theta is −0.08. About how much does one contract lose per day, all else equal?',o:[['$8'],['$0.08','Multiply by 100 for one contract.'],['$80','That\'s 10 times too much.'],['Nothing, because theta only matters at expiration','Theta works every day.']],a:0,ex:'−0.08 × 100 = −$8 per day.'},
{q:'Which Greek measures sensitivity to implied volatility?',o:[['Vega'],['Gamma','Gamma measures how delta changes.'],['Theta','Theta measures time decay.'],['Delta','Delta measures stock-price sensitivity.']],a:0,ex:'Vega = the change in option price per 1-point change in IV.'},
{q:'Gamma is usually highest for…',o:[['At-the-money options close to expiration'],['Deep ITM options with a year left','Those have low gamma, because delta is already near 1.'],['Far OTM options with a year left','Those have low gamma.'],['Stocks','Plain shares have no gamma, because their delta is always 1.']],a:0,ex:'ATM options near expiration can flip from worthless to valuable quickly, so delta changes fast.'}]});
